 const [data,setData]=useState<Data>({leads:[],tasks:[]});const [ready,setReady]=useState(false);const [page,setPage]=useState('Dashboard');const [query,setQuery]=useState('');const [source,setSource]=useState('All sources');const [stage,setStage]=useState('All stages');const [owner,setOwner]=useState('All owners');const [period,setPeriod]=useState('Last 30 days');
 const [inviteToken,setInviteToken]=useState('');const authChecked=useRef(false);const [quoteEdit,setQuoteEdit]=useState<{leadId:string;quote:Quote}|null>(null);const [selected,setSelected]=useState<string|null>(null);const [edit,setEdit]=useState<Lead|null>(null);const [taskEdit,setTaskEdit]=useState<Task|null>(null);const [notice,setNotice]=useState('');const [note,setNote]=useState('');const [user,setUser]=useState<User|null>(null);const [live,setLive]=useState(false);const [modal,setModal]=useState<string|null>(null);const [busy,setBusy]=useState(false);const [integration,setIntegration]=useState<Record<string,boolean>>({});const [selectedIds,setSelectedIds]=useState<string[]>([]);const [activityFilter,setActivityFilter]=useState('Upcoming');const [importText,setImportText]=useState('');const [menu,setMenu]=useState(false);const [target,setTarget]=useState(100000);const fileRef=useRef<HTMLInputElement>(null);
 function openDemo(){const savedTarget=Number(localStorage.getItem('eti-crm-target'));setTarget(savedTarget>0?savedTarget:100000);try{const raw=localStorage.getItem(storageKey);const parsed=raw?JSON.parse(raw):seedData();if(!Array.isArray(parsed.leads)||!Array.isArray(parsed.tasks))throw Error();setData(parsed);}catch{setData(seedData());}try{setTeam(demoTeam(JSON.parse(localStorage.getItem('eti-crm-demo-team')||'[]')));}catch{setTeam(demoTeam());}setDemo(true);setReady(true);setPage('Dashboard');}
 useEffect(()=>{if(ready&&demo&&!live){try{localStorage.setItem(storageKey,JSON.stringify(data));}catch{setNotice('Browser storage is full. Export your records before leaving.');}}},[data,ready,live,demo]);
