 async function saveLead(e:FormEvent){e.preventDefault();if(!edit)return;setBusy(true);try{if(edit.leadType==='corporate'&&!edit.company.trim())throw Error('Company name is required for a corporate lead.');if(!edit.program.trim())throw Error('Choose a programme from the list.');if(!edit.email.trim()&&!edit.phone.trim())throw Error('Add an email address or phone number.');const original=data.leads.find(l=>l.id===edit.id);if((!original||original.email.trim().toLowerCase()!==edit.email.trim().toLowerCase()||original.phone.replace(/\D/g,'')!==edit.phone.replace(/\D/g,''))&&data.leads.some(l=>l.id!==edit.id&&((edit.email&&l.email.toLowerCase()===edit.email.trim().toLowerCase())||(edit.phone&&l.phone.replace(/\D/g,'')===edit.phone.replace(/\D/g,'')))))throw Error('A lead with this email or phone already exists. Update the existing record.');await persist('leads',{...edit,name:edit.name.trim(),email:edit.email.trim(),updatedAt:new Date().toISOString()});setEdit(null);if(live)await loadLive();setNotice(!isSuperAdmin&&!edit.ownerId?'Lead submitted. A super admin must assign it before it appears in a salesperson’s workspace.':'Lead saved successfully.');}catch(e){setNotice((e as Error).message);}finally{setBusy(false);}}
