 function stageSelect(lead:Lead){return <select aria-label={`Stage for ${lead.name}`} className={`crm-stage-select crm-badge-${lead.stage.toLowerCase().replaceAll(' ','-')}`} value={lead.stage} disabled={savingRecord||busy||(live&&!isSuperAdmin&&lead.ownerId!==actor?.id)} onChange={e=>void move(lead,e.target.value as Stage)}>{stages.map(s=><option key={s} value={s}>{s}</option>)}</select>;}
 function temperatureSelect(lead:Lead){return <select aria-label={`Temperature for ${lead.name}`} className={`crm-temperature-select crm-badge-${(lead.temperature||'Warm').toLowerCase()}`} value={lead.temperature||'Warm'} disabled={savingRecord||busy||(live&&!isSuperAdmin&&lead.ownerId!==actor?.id)} onChange={e=>void changeTemperature(lead,e.target.value as Temperature)}>{['Hot','Warm','Cold'].map(t=><option key={t} value={t}>{t}</option>)}</select>;}
 function newQuote(leadId=''){const lead=data.leads.find(l=>l.id===leadId)||data.leads[0];if(!lead){setNotice('Add a lead before creating a quotation.');return;}setQuoteEdit({leadId:lead.id,quote:{id:crypto.randomUUID(),number:`ETI-${new Date().getFullYear()}-${crypto.randomUUID().slice(0,6).toUpperCase()}`,description:lead.program,quantity:1,unitPrice:lead.value,discount:0,tax:0,validUntil:new Date(Date.now()+14*86400000).toISOString().slice(0,10),status:'Draft',createdAt:new Date().toISOString()}});}
