 function exportQuote(lead:Lead,q:Quote){const esc=(s:unknown)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));download(`${q.number}.html`,`<!doctype html><html><head><meta charset="utf-8"><title>${esc(q.number)}</title><style>body{font:15px Arial;color:#263e30;max-width:800px;margin:60px auto;padding:30px}h1{font:38px Georgia}header{border-bottom:3px solid #b59c59;padding-bottom:25px}table{width:100%;border-collapse:collapse;margin:35px 0}td,th{padding:16px 10px;text-align:left;border-bottom:1px solid #ddd}aside{text-align:right}small{color:#7e897c}@media print{body{margin:0}}</style></head><body><header><h1>entrepôt</h1><p>Entrepôt Training Institute · UAE · etiworld.ae</p></header><h2>Training quotation ${esc(q.number)}</h2><p>${esc(lead.name)}<br>${esc(lead.company)}<br>${esc(lead.email)}</p><small>Status: ${esc(q.status)} · Valid until ${esc(q.validUntil)}</small><table><thead><tr><th>Programme / service</th><th>Quantity</th><th>Unit price (AED)</th><th>Amount (AED)</th></tr></thead><tbody><tr><td>${esc(q.description)}</td><td>${q.quantity}</td><td>${money(q.unitPrice)}</td><td>${money(q.quantity*q.unitPrice)}</td></tr></tbody></table><aside><p>Discount: AED ${money(q.discount)}</p><p>Tax rate: ${q.tax}%</p><h2>Total: AED ${new Intl.NumberFormat('en-AE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(quoteTotal(q))}</h2></aside><p><small>Quotation only. Programme availability, delivery dates and payment terms must be confirmed by Entrepôt Training Institute. This document is not a tax invoice.</small></p></body></html>`,'text/html');setNotice('Quotation downloaded. Open it to print or save as PDF.');}
 function confirmBulkDelete(rows:Lead[]){if(!live||!isSuperAdmin||!rows.length)return;setDeleteTargets(rows.map(l=>({id:l.id,version:l.version,name:l.name})));setModal('delete-bulk');}
 function newTask(leadId=''){setTaskEdit({id:crypto.randomUUID(),title:'',leadId,due:localDateTime(new Date().toISOString()).slice(0,10),ownerId:live?(leadId?data.leads.find(l=>l.id===leadId)?.ownerId:actor?.id):undefined,owner:live?(data.leads.find(l=>l.id===leadId)?.owner||actor?.name||'Unassigned'):owners[1],type:'Call',done:false});}
