 const filtered=sectionLeads.filter(l=>inDateRange(l.proposalSentDate,proposalFrom,proposalTo)&&inDateRange(enrolmentDay(l),enrolmentFrom,enrolmentTo)&&(!receivedFrom||receivedDate(l)>=receivedFrom)&&(!receivedTo||receivedDate(l)<=receivedTo)&&(page!=='Corporate leads'||!category||l.corporateCategory===category||(!l.corporateCategory&&corporateCourses.some(c=>c.title===l.program&&c.category===category)))&&(!course||l.program===course)&&(`${l.name} ${l.email} ${l.company} ${l.program}`.toLowerCase().includes(query.toLowerCase()))&&(source==='All sources'||l.source===source)&&(stage==='All stages'||l.stage===stage)&&(owner==='All owners'||l.owner===owner)&&(temperature==='All temperatures'||(l.temperature||'Warm')===temperature));
 const now=new Date();const scoped=data.leads.filter(l=>period==='All time'||(period==='Last 30 days'?new Date(l.createdAt).getTime()>=Date.now()-30*86400000:new Date(l.createdAt).getMonth()===now.getMonth()&&new Date(l.createdAt).getFullYear()===now.getFullYear()));
 const open=scoped.filter(l=>!['Enrolled','Lost'].includes(l.stage));const won=scoped.filter(l=>l.stage==='Enrolled');const pipeline=open.reduce((n,l)=>n+l.value,0);const revenue=won.reduce((n,l)=>n+l.value,0);const conversion=scoped.length?Math.round(won.length/scoped.length*100):0;const pending=data.tasks.filter(t=>!t.done).sort((a,b)=>a.due.localeCompare(b.due));const current=data.leads.find(l=>l.id===selected);const total=sectionLeads.length;
 const chartEnd=new Date();chartEnd.setHours(24,0,0,0);const bins=Array.from({length:6},(_,i)=>{const end=chartEnd.getTime()-(5-i)*5*86400000,start=end-5*86400000;return {label:date(new Date(end-86400000).toISOString()),counts:sources.slice(0,3).map(s=>scoped.filter(l=>l.source===s&&Date.parse(l.createdAt)>=start&&Date.parse(l.createdAt)<end).length)};});const chartMax=Math.max(1,...bins.flatMap(b=>b.counts));
 const exportCSV=()=>{const rows=selectedIds.length?filtered.filter(l=>selectedIds.includes(l.id)):filtered;download('eti-leads.csv',[['name','email','phone','company','program','source','stage','owner','value','priority','temperature','closeDate','followUpAt','leadType','designation','industry','participants','deliveryMode','trainingRequirements','corporateCategory','paymentMethod','paymentDate','paymentPlan','emiDates','amountPaid','nextPaymentDate','proposalSentDate','enrolmentDate','leadReceivedDate'].map(csvEscape).join(','),...rows.map(l=>[l.name,l.email,l.phone,l.company,l.program,l.source,l.stage,l.owner,l.value,l.priority,l.temperature||'Warm',l.closeDate,l.followUpAt||'',l.leadType||'individual',l.designation,l.industry,l.participants,l.deliveryMode,l.trainingRequirements,l.corporateCategory,l.paymentMethod,l.paymentDate,l.paymentPlan,(l.emiDates||[]).join(';'),l.amountPaid,l.nextPaymentDate,l.proposalSentDate,l.enrolmentDate,receivedDate(l)].map(csvEscape).join(','))].join('\r\n'));setNotice(`${rows.length} leads exported.`);};
 async function importCSV(){setBusy(true);try{const rows=parseCSV(importText);const headers=rows.shift()?.map(importHeader)||[];if(!headers.includes('name'))throw Error('CSV must include a name column.');if(rows.length>500)throw Error('Import up to 500 rows at a time.');const known=new Set(data.leads.flatMap(l=>[l.email.toLowerCase(),l.phone.replace(/\D/g,'')]).filter(Boolean));const prepared:Lead[]=[];let duplicates=0;for(const [i,row] of rows.entries()){const obj=Object.fromEntries(headers.map((h,j)=>[h,(row[j]||'').trim()]));if(obj.phone?.startsWith("'+"))obj.phone=obj.phone.slice(1);if(obj.followUpAt&&!Number.isFinite(Date.parse(obj.followUpAt)))throw Error(`Row ${i+2}: invalid follow-up date/time.`);if(obj.closeDate&&!validCloseDate(obj.closeDate))throw Error(`Row ${i+2}: invalid close date.`);if(!obj.name||(!obj.email&&!obj.phone))throw Error(`Row ${i+2}: name and email or phone are required.`);if(obj.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(obj.email))throw Error(`Row ${i+2}: invalid email.`);if(obj.value&&(!Number.isFinite(Number(obj.value))||Number(obj.value)<0))throw Error(`Row ${i+2}: invalid deal value.`);const keys=[obj.email?.toLowerCase(),obj.phone?.replace(/\D/g,'')].filter(Boolean);if(keys.some(k=>known.has(k))){duplicates++;continue;}keys.forEach(k=>known.add(k));prepared.push({...blankLead(),leadType:obj.leadType==='corporate'||page==='Corporate leads'?'corporate':'individual',paymentMethod:(obj.paymentMethod||'') as Lead['paymentMethod'],paymentDate:obj.paymentDate||'',leadReceivedDate:parseLeadDate(obj.leadReceivedDate||''),nextPaymentDate:obj.nextPaymentDate||'',proposalSentDate:obj.proposalSentDate||'',enrolmentDate:obj.enrolmentDate||'',amountPaid:obj.amountPaid?Number(obj.amountPaid):null,paymentPlan:(obj.paymentPlan||'') as Lead['paymentPlan'],emiDates:obj.emiDates?obj.emiDates.split(';').map(d=>d.trim()):[],corporateCategory:obj.corporateCategory||'',designation:obj.designation||'',industry:obj.industry||'',participants:obj.participants?Number(obj.participants):undefined,deliveryMode:(obj.deliveryMode||'') as Lead['deliveryMode'],trainingRequirements:obj.trainingRequirements||'',name:obj.name,email:obj.email||'',phone:obj.phone||'',company:obj.company||'',program:obj.program||programs[0],value:Number(obj.value)||0,source:sources.includes(obj.source as Lead['source'])?obj.source as Lead['source']:'Manual',stage:stages.includes(obj.stage as Stage)?obj.stage as Stage:'New',temperature:(['Hot','Warm','Cold'].includes(obj.temperature)?obj.temperature:'Warm') as Temperature,priority:(['High','Medium','Low'].includes(obj.priority)?obj.priority:'Medium') as Lead['priority'],closeDate:obj.closeDate||'',followUpAt:obj.followUpAt?new Date(obj.followUpAt).toISOString():'',...importOwner(obj.owner||'',team,live,isSuperAdmin)});}let imported=0;if(live){if(prepared.length){const result=await runCommand({action:'import',records:prepared});imported=result.imported;duplicates+=result.skipped;await loadLive();}}else for(const l of prepared){try{await persist('leads',l);imported++;}catch(error){throw Error(`${imported} saved; import stopped: ${(error as Error).message}. Correct the problem and retry; saved contacts will be skipped.`);}}setModal(null);setImportText('');setNotice(`${imported} leads imported. ${duplicates} duplicates skipped.`);}catch(e){setNotice((e as Error).message);}finally{setBusy(false);}}
